input.command:
cd /tmp && for r in 2.05 2.06 2.07; do for p in "/api/v1/releases/$r/sids/d1nqda_" "/api/v1/releases/$r/sids/d1nqda_/parents"; do out=$(curl -s -w "\nHTTP %{http_code}" "http://127.0.0.1:41635$p"); echo "== $p"; echo "$out" | python3 -I -c '
import json,sys
raw=sys.stdin.read()
body,code=raw.rsplit("\nHTTP ",1)
print("HTTP",code.strip())
try:
    d=json.loads(body)
except Exception as e:
    print("nonjson", body[:300]); sys.exit()
if "node" in d:
    n=d["node"]; print("node", n["sunid"], n["sid"], n["sccs"], n["description"], "parent", n.get("parent"))
elif "parents" in d:
    for x in d["parents"]: print("  ", x["sunid"], x["sccs"], x["level"]["code"], x["description"])
else:
    print(body[:300])
'; done; done

